class Solution {
public:
    long long minimalKSum(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        long long ans = (long long)k * (k + 1) / 2;
        long long cur = k;
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            if ((long long)nums[i] <= cur) {
                ans = ans - nums[i] + (cur + 1);
                cur++;
            }
        }
        return ans;
    }
};
